begin;
alter table public.mta_audit_events add column if not exists hash_version text not null default 'AUDIT-HASH-v1', add column if not exists previous_hash text, add column if not exists event_hash text;
create or replace function private.mta_audit_canonical_material(p_id uuid,p_action text,p_resource_type text,p_resource_id text,p_result text,p_actor_user_id uuid,p_request_id text,p_correlation_id text,p_occurred_at timestamptz,p_metadata jsonb,p_previous_hash text) returns text language sql immutable set search_path='' as $$ select 'AUDIT-HASH-v1|'||coalesce(p_previous_hash,'GENESIS')||'|'||jsonb_build_object('id',p_id,'action',p_action,'resourceType',p_resource_type,'resourceId',p_resource_id,'result',p_result,'actorUserId',p_actor_user_id,'requestId',p_request_id,'correlationId',p_correlation_id,'occurredAt',p_occurred_at,'metadata',coalesce(p_metadata,'{}'::jsonb))::text $$;
do $$ declare r record; v_previous text:=null; v_hash text; begin for r in select * from public.mta_audit_events order by occurred_at asc,id asc loop v_hash:=encode(extensions.digest(private.mta_audit_canonical_material(r.id,r.action,r.resource_type,r.resource_id,r.result,r.actor_user_id,r.request_id,r.correlation_id,r.occurred_at,coalesce(r.metadata,'{}'::jsonb),v_previous),'sha256'),'hex'); update public.mta_audit_events set hash_version='AUDIT-HASH-v1',previous_hash=v_previous,event_hash=v_hash where id=r.id; v_previous:=v_hash; end loop; end $$;
create or replace function private.mta_audit_before_insert() returns trigger language plpgsql security definer set search_path='' as $$ declare v_previous text; begin perform pg_advisory_xact_lock(hashtext('MTA_DETENI_AUDIT_CHAIN_V1')); select event_hash into v_previous from public.mta_audit_events order by occurred_at desc,id desc limit 1; new.hash_version:='AUDIT-HASH-v1'; new.previous_hash:=v_previous; new.event_hash:=encode(extensions.digest(private.mta_audit_canonical_material(new.id,new.action,new.resource_type,new.resource_id,new.result,new.actor_user_id,new.request_id,new.correlation_id,new.occurred_at,coalesce(new.metadata,'{}'::jsonb),v_previous),'sha256'),'hex'); return new; end $$;
drop trigger if exists mta_audit_before_insert_hash on public.mta_audit_events;
create trigger mta_audit_before_insert_hash before insert on public.mta_audit_events for each row execute function private.mta_audit_before_insert();
create or replace function private.mta_audit_immutable() returns trigger language plpgsql security definer set search_path='' as $$ begin raise exception 'AUDIT_IMMUTABLE_HISTORY'; end $$;
drop trigger if exists mta_audit_immutable_update on public.mta_audit_events;
create trigger mta_audit_immutable_update before update on public.mta_audit_events for each row execute function private.mta_audit_immutable();
drop trigger if exists mta_audit_immutable_delete on public.mta_audit_events;
create trigger mta_audit_immutable_delete before delete on public.mta_audit_events for each row execute function private.mta_audit_immutable();
create or replace function public.mta_verify_audit_integrity() returns jsonb language plpgsql security definer set search_path='' as $$ declare r record; v_previous text:=null; v_expected text; v_count bigint:=0; begin for r in select * from public.mta_audit_events order by occurred_at asc,id asc loop v_count:=v_count+1; if r.hash_version<>'AUDIT-HASH-v1' or r.previous_hash is distinct from v_previous then return jsonb_build_object('ok',false,'status','INTEGRITY_COMPROMISED','checked',v_count,'eventId',r.id); end if; v_expected:=encode(extensions.digest(private.mta_audit_canonical_material(r.id,r.action,r.resource_type,r.resource_id,r.result,r.actor_user_id,r.request_id,r.correlation_id,r.occurred_at,coalesce(r.metadata,'{}'::jsonb),v_previous),'sha256'),'hex'); if r.event_hash is distinct from v_expected then return jsonb_build_object('ok',false,'status','INTEGRITY_COMPROMISED','checked',v_count,'eventId',r.id); end if; v_previous:=r.event_hash; end loop; return jsonb_build_object('ok',true,'status','INTEGRITY_VERIFIED','checked',v_count,'lastHash',v_previous); end $$;
revoke all on function public.mta_verify_audit_integrity() from public,anon,authenticated;
grant execute on function public.mta_verify_audit_integrity() to service_role;
commit;